import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/bivariate/bivariate_2023_no2_crime.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

borough_neighbors = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in borough_neighbors:
        borough_neighbors[borough] = []
    borough_neighbors[borough].append(neighbor)

df['spatial_lag_crime'] = np.nan
for index, row in df.iterrows():
    borough = row['borough']
    if borough in borough_neighbors:
        neighbors = borough_neighbors[borough]
        neighbor_crimes = []
        for neighbor in neighbors:
            neighbor_row = df[df['borough'] == neighbor]
            if not neighbor_row.empty:
                crime = neighbor_row['Crime_value'].values[0]
                neighbor_crimes.append(crime)
        if len(neighbor_crimes) > 0:
            avg_crime = np.mean(neighbor_crimes)
            df.at[index, 'spatial_lag_crime'] = avg_crime
        else:
            df.at[index, 'spatial_lag_crime'] = np.nan
    else:
        df.at[index, 'spatial_lag_crime'] = np.nan

observed_df = df.dropna(subset=['NO2_value', 'spatial_lag_crime'])
observed_r = observed_df['NO2_value'].corr(observed_df['spatial_lag_crime'])

num_permutations = 500
permuted_rs = []

for _ in range(num_permutations):
    shuffled_crime = df['Crime_value'].sample(frac=1).values
    temp_df = df.copy()
    temp_df['shuffled_crime'] = shuffled_crime
    temp_df['spatial_lag_shuffled'] = np.nan
    for idx, row in temp_df.iterrows():
        borough = row['borough']
        if borough in borough_neighbors:
            neighbors = borough_neighbors[borough]
            neighbor_crimes = []
            for neighbor in neighbors:
                neighbor_row = temp_df[temp_df['borough'] == neighbor]
                if not neighbor_row.empty:
                    crime = neighbor_row['shuffled_crime'].values[0]
                    neighbor_crimes.append(crime)
            if len(neighbor_crimes) > 0:
                avg_crime = np.mean(neighbor_crimes)
                temp_df.at[idx, 'spatial_lag_shuffled'] = avg_crime
            else:
                temp_df.at[idx, 'spatial_lag_shuffled'] = np.nan
        else:
            temp_df.at[idx, 'spatial_lag_shuffled'] = np.nan
    permuted_df = temp_df.dropna(subset=['NO2_value', 'spatial_lag_shuffled'])
    if not permuted_df.empty:
        r = permuted_df['NO2_value'].corr(permuted_df['spatial_lag_shuffled'])
        permuted_rs.append(r)

observed_abs = abs(observed_r)
count = sum(1 for r in permuted_rs if abs(r) >= observed_abs)
p_value = count / len(permuted_rs)

print("Observed correlation (r):", observed_r)
print("p-value:", p_value)

if observed_r > 0 and p_value < 0.05:
    result = "POSITIVE"
elif observed_r < 0 and p_value < 0.05:
    result = "NEGATIVE"
else:
    result = "NOT SIGNIFICANT"

print(f"FINAL ANSWER: {result} (test statistic (a real number) = {observed_r}, p = {p_value})")
